export const SECTORS={
 'Estética':{example:'Ej. corte + tinte, sábado 4 pm',categories:['Productos','Alquiler','Transporte'],tips:['Registra citas y pide una seña para evitar faltas.','Calcula el costo por servicio (productos + tu tiempo).']},
 'Decoración':{example:'Ej. arco de globos para cumpleaños',categories:['Materiales','Transporte','Alquiler de equipos'],tips:['Anota medidas, lugar y fecha de montaje en cada pedido.','Pide adelanto al confirmar el evento.']},
 'Repostería':{example:'Ej. torta de chocolate x1',categories:['Insumos','Empaque','Delivery'],tips:['Calcula el costo por receta, no por ingrediente suelto.','Programa recordatorios de entrega 1 día antes.']},
 'Ropa nueva':{example:'Ej. polo talla M x2',categories:['Mercadería','Empaque','Publicidad'],tips:['Registra tallas y colores por cliente.','Suma envío y empaque a tus costos.']},
 'Second hand':{example:'Ej. casaca jean talla S',categories:['Compra de prendas','Lavado','Envío'],tips:['Anota lo que pagaste por cada prenda.','Define un margen mínimo para no vender a pérdida.']},
 'Otro':{example:'Ej. servicio o producto pedido',categories:['Insumos','Transporte','Publicidad'],tips:['Anota cada pedido apenas llegue, así no se te pasa nada.','Revisa tu ganancia real cada semana.']}
};
export const STATES=['Pendiente','En proceso','Entregado'];
export const money=n=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN',minimumFractionDigits:2}).format(n||0);
export const round=n=>Math.round((n+Number.EPSILON)*100)/100;
export const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Lima',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
export const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const empty=()=>({version:3,business:'',sector:'',owner:'',orders:[],movements:[],reminders:[],products:[],calculator:{materials:20,other:5,percent:40,units:1,mode:'markup'}});
export function calculate({materials,other,percent,units,mode='markup'}){if(![materials,other,percent,units].every(Number.isFinite)||materials<0||other<0||percent<0||units<1||!Number.isInteger(units)||!['markup','margin'].includes(mode)||(mode==='margin'&&percent>=100))throw Error('Revisa los valores: costos y porcentaje no negativos; unidades enteras desde 1. El margen sobre venta debe ser menor al 100%.');const cost=(materials+other)/units;const rawPrice=mode==='margin'?cost/(1-percent/100):cost*(1+percent/100);const price=round(rawPrice);return {cost:round(cost),price,profit:round(price-cost),actualMargin:price?round((price-cost)/price*100):0};}
export function clients(orders){const map=new Map();for(const o of orders){const k=o.client.trim().toLocaleLowerCase('es');const c=map.get(k)||{name:o.client,phone:'',count:0,total:0};c.count++;c.total=round(c.total+o.amount);if(o.phone)c.phone=o.phone;map.set(k,c)}return [...map.values()].sort((a,b)=>b.total-a.total);}
export function totals(data,month='all'){const include=d=>month==='all'||!d||d.startsWith(month);const sales=data.orders.filter(o=>o.state===2&&include(o.deliveredAt||o.created));const movements=data.movements.filter(m=>include(m.date));const auto=round(sales.reduce((s,o)=>s+o.amount,0));const manual=round(movements.filter(m=>m.type==='Ingreso').reduce((s,m)=>s+m.amount,0));const expenses=round(movements.filter(m=>m.type==='Gasto').reduce((s,m)=>s+m.amount,0));return {auto,manual,income:round(auto+manual),expenses,net:round(auto+manual-expenses),sales,movements,pending:data.orders.filter(o=>o.state!==2).length,receivable:round(data.orders.filter(o=>o.state!==2).reduce((s,o)=>s+o.amount,0))};}
const text=(v,max=1000)=>String(v??'').slice(0,max).trim();
const amount=v=>{const n=Number(v??0);if(!Number.isFinite(n)||n<0||n>1e9)throw Error('El respaldo contiene montos inválidos.');return round(n)};
const date=v=>{if(!v)return '';const s=String(v);if(!/^\d{4}-\d{2}-\d{2}$/.test(s)||isNaN(Date.parse(s+'T12:00:00Z'))||new Date(s+'T12:00:00Z').toISOString().slice(0,10)!==s)throw Error('El respaldo contiene fechas inválidas.');return s};
export function normalize(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('Selecciona un archivo de respaldo de EmprendeCopilot.');const legacy=Array.isArray(raw.p)&&Array.isArray(raw.m)&&Array.isArray(raw.r);if(!legacy&&!(raw.version===3&&Array.isArray(raw.orders)&&Array.isArray(raw.movements)&&Array.isArray(raw.reminders)))throw Error('Formato no reconocido. Se admite ec2 y respaldos de la versión 3.');const d=empty();d.business=text(legacy?raw.neg:raw.business,120);d.owner=text(raw.owner,80);const sector=legacy?raw.rubro:raw.sector;d.sector=SECTORS[sector]?sector:'';const arrays=legacy?[raw.p,raw.m,raw.r,[]]:[raw.orders,raw.movements,raw.reminders,raw.products||[]];if(arrays.some(a=>!Array.isArray(a)||a.length>10000))throw Error('El respaldo supera el límite de registros.');d.orders=arrays[0].map(o=>{if(!o||typeof o!=='object')throw Error('Pedido inválido.');const state=Number(legacy?o.e:o.state);const client=text(legacy?o.c:o.client,120),detail=text(legacy?o.d:o.detail);if(!client||!detail||![0,1,2].includes(state))throw Error('Un pedido no tiene cliente, detalle o estado válido.');return {id:text(o.id,80)||uid(),client,detail,phone:text(legacy?o.t:o.phone,40),amount:amount(legacy?o.m:o.amount),state,delivery:date(o.delivery),created:date(o.created),deliveredAt:date(o.deliveredAt),notes:text(o.notes)}});d.movements=arrays[1].map(m=>{const type=legacy?m.t:m.type,concept=text(legacy?m.c:m.concept,250);if(!['Ingreso','Gasto'].includes(type)||!concept)throw Error('Movimiento inválido.');return {id:text(m.id,80)||uid(),type,amount:amount(legacy?m.v:m.amount),concept,date:date(m.date),category:text(m.category,80)}});d.reminders=arrays[2].map(r=>{const title=text(legacy?r.t:r.title,250);if(!title)throw Error('Recordatorio inválido.');const old={'💰':'Pago','📦':'Entrega','📅':'Cita'};const kind=legacy?old[r.k]:r.kind;return {id:text(r.id,80)||uid(),title,kind:['Pago','Entrega','Cita'].includes(kind)?kind:'Cita',date:date(legacy?r.f:r.date),time:/^([01]\d|2[0-3]):[0-5]\d$/.test(r.time||'')?r.time:'',done:!!(legacy?r.ok:r.done)}});d.products=arrays[3].map(p=>{const name=text(p.name,150);if(!name)throw Error('Producto inválido.');return {id:text(p.id,80)||uid(),name,cost:amount(p.cost),price:amount(p.price)}});if(raw.calculator){try{calculate(raw.calculator);d.calculator={...d.calculator,...raw.calculator}}catch{}}for(const arr of [d.orders,d.movements,d.reminders,d.products]){const ids=new Set();for(const item of arr){if(ids.has(item.id))item.id=uid();ids.add(item.id)}}return d;}
export function recommendations(data){const t=totals(data),pending=data.reminders.filter(r=>!r.done),due=pending.filter(r=>r.date&&r.date<today());const list=[];if(due.length)list.push({title:`${due.length} recordatorio${due.length>1?'s':''} vencido${due.length>1?'s':''}`,body:'Revisa los pendientes y marca lo que ya resolviste.',page:'reminders',tone:'warning'});if(t.pending)list.push({title:`${t.pending} pedido${t.pending>1?'s':''} por entregar`,body:`Importe de pedidos pendientes: ${money(t.receivable)}. No equivale a pagos por cobrar.`,page:'orders',tone:'purple'});if(t.net<0)list.push({title:'Tus gastos superan los ingresos',body:`La diferencia registrada es ${money(Math.abs(t.net))}. Revisa costos y precios.`,page:'finances',tone:'warning'});if(data.orders.length&&!data.movements.some(m=>m.type==='Gasto'))list.push({title:'Completa tus costos reales',body:'Aún no registras gastos. El balance todavía no refleja los costos de tu negocio.',page:'finances',tone:'purple'});const cfg=SECTORS[data.sector]||SECTORS.Otro;if(list.length<3)list.push({title:'Una idea para tu rubro',body:cfg.tips[0],page:'costs',tone:'mint'});return list.slice(0,3);}
